<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'; import { Plus, Pencil, EyeOff, X, Upload } from 'lucide-vue-next'; import { http, errorMessage } from '../../api/http'; import type { Category, Product, Page } from '../../types'; import { money, fallback } from '../../utils/format'; import Pagination from '../../components/Pagination.vue'; import LoadingState from '../../components/LoadingState.vue'; import FormField from '../../components/FormField.vue'; import ConfirmDialog from '../../components/ConfirmDialog.vue'
const result = ref<Page<Product>>(), categories = ref<Category[]>([]), filters = reactive({ search: '', categoryId: '', isActive: '' }), loading = ref(true), busy = ref(false), uploading = ref(false), error = ref(''), success = ref(''), editing = ref<number | null>(null), showForm = ref(false), target = ref<Product>();
const empty = () => ({ name: '', slug: '', sku: '', categoryId: 0, author: '', publisher: '', description: '', price: 100000, stockQuantity: 0, isActive: true, isFeatured: false, version: 0, images: [] as string[] }); const form = reactive(empty());
async function load(page = 1) { loading.value = true; try { result.value = (await http.get<Page<Product>>('/admin/products', { params: { ...filters, page } })).data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function edit(p?: Product) { error.value = ''; try { if (p) { const { data } = await http.get<Product>(`/admin/products/${p.id}`); Object.assign(form, data, { images: [...data.images] }); editing.value = p.id } else { Object.assign(form, empty(), { categoryId: categories.value[0]?.id || 0 }); editing.value = null } showForm.value = true; window.scrollTo({ top: 0, behavior: 'smooth' }) } catch (e) { error.value = errorMessage(e) } }
async function save() { busy.value = true; error.value = ''; try { if (editing.value) await http.put(`/admin/products/${editing.value}`, form); else await http.post('/admin/products', form); success.value = 'Đã lưu sản phẩm.'; showForm.value = false; await load() } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
async function upload(e: Event) { const file = (e.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) { error.value = 'Ảnh tối đa 5 MB.'; return } uploading.value = true; error.value = ''; try { const body = new FormData(); body.append('file', file); const { data } = await http.post('/admin/uploads/images', body); form.images.push(data.imageUrl) } catch (e) { error.value = errorMessage(e) } finally { uploading.value = false; (e.target as HTMLInputElement).value = '' } }
async function hide() { const id = target.value?.id; target.value = undefined; try { await http.delete(`/admin/products/${id}`); await load() } catch (e) { error.value = errorMessage(e) } }
onMounted(async () => { await load(); try { const all: Category[] = []; let page = 1, pages = 1; do { const { data } = await http.get<Page<Category>>('/admin/categories', { params: { page, pageSize: 50 } }); all.push(...data.items); pages = data.totalPages; page++ } while (page <= pages); categories.value = all } catch (e) { error.value = errorMessage(e) } })
</script>
<template><div class="section-heading"><div><span class="eyebrow">CHĂM CHÚT TỪNG CUỐN SÁCH</span><h1>Quản lý sản phẩm</h1></div><button class="btn" @click="edit()"><Plus :size="18" /> Thêm sách</button></div><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="success" role="status" class="alert success">{{ success }}</p><section v-if="showForm" class="panel"><div class="section-heading"><h2>{{ editing ? 'Chỉnh sửa sách' : 'Thêm sách mới' }}</h2><button v-if="editing" class="text-link" @click="edit({ id: editing } as Product)">Tải lại bản mới nhất (bỏ thay đổi form)</button></div><form class="form-grid" @submit.prevent="save"><FormField label="Tên sách" id="p-name"><input id="p-name" v-model="form.name" required maxlength="200"></FormField><FormField label="Slug duy nhất" id="p-slug"><input id="p-slug" v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="180"></FormField><FormField label="SKU duy nhất" id="p-sku"><input id="p-sku" v-model="form.sku" required maxlength="100"></FormField><FormField label="Danh mục" id="p-category"><select id="p-category" v-model.number="form.categoryId" required><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}{{ c.isActive ? '' : ' (đã ẩn)' }}</option></select></FormField><FormField label="Tác giả" id="p-author"><input id="p-author" v-model="form.author" required maxlength="200"></FormField><FormField label="Nhà xuất bản" id="p-publisher"><input id="p-publisher" v-model="form.publisher" required maxlength="200"></FormField><FormField label="Giá (VND)" id="p-price"><input id="p-price" v-model.number="form.price" type="number" min="1" max="1000000000" required></FormField><FormField label="Tồn kho" id="p-stock" hint="Hệ thống từ chối nếu tồn kho đã thay đổi khi bạn đang sửa."><input id="p-stock" v-model.number="form.stockQuantity" type="number" min="0" max="1000000" step="1" required></FormField><FormField label="Mô tả" id="p-description"><textarea id="p-description" v-model="form.description" required maxlength="4000" rows="4"></textarea></FormField><div class="field"><label for="p-image"><Upload :size="15" /> Ảnh bìa (JPEG, PNG, WebP ≤ 5 MB)</label><input id="p-image" type="file" accept="image/jpeg,image/png,image/webp" :disabled="uploading || form.images.length >= 8" @change="upload"><small v-if="uploading">Đang kiểm tra và tải ảnh…</small><div class="upload-previews"><div v-for="(url, i) in form.images" :key="url"><img :src="url" alt="Ảnh sách" @error="fallback"><button type="button" class="icon-btn" aria-label="Bỏ ảnh" @click="form.images.splice(i, 1)"><X :size="15" /></button></div></div></div><div class="actions"><label class="check-label"><input v-model="form.isActive" type="checkbox"> Đang bán</label><label class="check-label"><input v-model="form.isFeatured" type="checkbox"> Nổi bật</label></div><div class="actions"><button class="btn" :disabled="busy || uploading">{{ busy ? 'Đang lưu…' : 'Lưu sản phẩm' }}</button><button type="button" class="btn secondary" @click="showForm = false">Đóng</button></div></form></section><section class="panel"><form class="toolbar" @submit.prevent="load()"><input v-model="filters.search" placeholder="Tên, SKU hoặc tác giả…" aria-label="Tìm sản phẩm"><select v-model="filters.categoryId" aria-label="Lọc danh mục"><option value="">Tất cả danh mục</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select><select v-model="filters.isActive" aria-label="Trạng thái bán"><option value="">Mọi trạng thái</option><option value="true">Đang bán</option><option value="false">Ngừng bán</option></select><button class="btn secondary">Lọc</button></form><LoadingState v-if="loading" /><div v-else class="table-wrap"><table><thead><tr><th>Sách</th><th>Danh mục</th><th>Giá</th><th>Tồn</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="p in result?.items" :key="p.id"><td><div class="table-product"><img :src="p.images[0] || '/fallback.svg'" :alt="p.name" @error="fallback"><div><strong>{{ p.name }}</strong><small>{{ p.sku }}</small></div></div></td><td>{{ p.categoryName }}</td><td>{{ money(p.price) }}</td><td :class="p.stockQuantity <= 2 ? 'error' : ''">{{ p.stockQuantity }}</td><td><span class="badge" :class="p.isActive ? 'paid' : 'cancelled'">{{ p.isActive ? 'Đang bán' : 'Ngừng bán' }}</span><small v-if="p.isFeatured">Nổi bật</small></td><td><div class="actions"><button class="icon-btn" :aria-label="`Sửa ${p.name}`" @click="edit(p)"><Pencil :size="17" /></button><button class="icon-btn" :disabled="!p.isActive" :aria-label="`Ngừng bán ${p.name}`" @click="target = p"><EyeOff :size="17" /></button></div></td></tr><tr v-if="!result?.items.length"><td colspan="6">Không có sách phù hợp.</td></tr></tbody></table></div><Pagination v-if="result" :page="result.page" :total-pages="result.totalPages" @change="load" /></section><ConfirmDialog :open="!!target" title="Ngừng bán sách này?" message="Sách sẽ bị ẩn khỏi cửa hàng. Không xóa dữ liệu hoặc lịch sử đơn hàng." @close="target = undefined" @confirm="hide" /></template>